class Solution:
    def minEatingSpeed(self, piles: List[int], h: int) -> int:
        l, r = 1, max(piles)
        res = r

        while l <= r:
            m = l + (r - l) // 2

            hours = 0
            for i, p in enumerate(piles):
                hours += math.ceil(p / m)

            if hours <= h:
                res = m
                r = m - 1
            else:
                l = m + 1

        return res

